 authority:=custodial_leadership_private.notification_credential(NEW.credential_id);
 IF authority IS NULL OR authority->>'managerId' IS DISTINCT FROM NEW.manager_id::text
 OR(TG_TABLE_NAME='ops_manager_push_devices' AND authority->>'kind'='CUSTODIAL_LEADERSHIP_REGISTRATION'
 AND authority->>'deviceId' IS DISTINCT FROM to_jsonb(NEW)->>'device_id')
 THEN RAISE EXCEPTION 'Notification record must belong to its current typed manager credential' USING ERRCODE='23514';END IF;
 NEW.updated_at:=now();RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.mz_reconcile_employee_push_credential_state()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_reason text;
begin
  -- Only the reviewed direct effect-1 AFTER ROW caller may suppress derived work.
  if TG_OP = 'UPDATE' and TG_LEVEL = 'ROW' and TG_WHEN = 'AFTER'
    and TG_TABLE_SCHEMA = 'public' and TG_TABLE_NAME = 'device_auth_credentials'
    and TG_NAME = 'trg_mz_reconcile_employee_push_credential_state' and TG_NARGS = 0
    and TG_RELID = pg_catalog.to_regclass('public.device_auth_credentials')
    and pg_catalog.pg_trigger_depth() = 1
    and current_user = session_user and current_user = 'postgres' then
    if custodial_dr.immutable_original_authority_guard_matches(TG_RELID,TG_OP) is true then
      declare v_original_authority custodial_dr.immutable_original_authority_scopes;
        v_original_unrevoked public.device_auth_credentials;
      begin
        select * into strict v_original_authority from custodial_dr.immutable_original_authority_scopes
          where database_oid=(select oid from pg_catalog.pg_database where datname=current_database())
            and backend_pid=pg_catalog.pg_backend_pid() and transaction_id=pg_catalog.txid_current();
        v_original_unrevoked:=NEW;
        v_original_unrevoked.revoked_at:=OLD.revoked_at;
        v_original_unrevoked.revoked_reason:=OLD.revoked_reason;
        if v_original_authority.phase is distinct from 'RUNNING'
          or v_original_authority.completed_step is distinct from 0
          or v_original_authority.active_table_oid is distinct from TG_RELID
          or v_original_authority.owner_oid is distinct from (select oid from pg_catalog.pg_roles where rolname=session_user)
          or v_original_authority.result is not null or v_original_authority.counts is distinct from '{}'::jsonb
          or OLD.revoked_at is not null or NEW.revoked_at is null
          or NEW.revoked_reason is distinct from ('disaster_restore_generation_'||v_original_authority.authority_generation::text)
          or pg_catalog.record_image_eq(v_original_unrevoked,OLD) is not true then
          raise exception using errcode='55000',message='Original employee push authority row differs';
        end if;
        if custodial_dr.immutable_original_authority_guard_matches(TG_RELID,TG_OP) is not true
          or (select pg_catalog.to_jsonb(s) from custodial_dr.immutable_original_authority_scopes s
            where database_oid=v_original_authority.database_oid and backend_pid=v_original_authority.backend_pid
              and transaction_id=v_original_authority.transaction_id) is distinct from pg_catalog.to_jsonb(v_original_authority) then
          raise exception using errcode='55000',message='Original employee push authority scope changed';
        end if;
        return NEW;
      end;
    end if;
  end if;
  if new.revoked_at is null and new.expires_at>clock_timestamp() then
    return new;
  end if;
  v_reason:=case when new.revoked_at is not null then 'device_credential_revoked' else 'device_credential_expired' end;
  update public.employee_push_registrations
     set active=false,revoked_at=coalesce(revoked_at,clock_timestamp()),revoked_reason=v_reason,updated_at=clock_timestamp()
   where credential_id=new.credential_id and (active=true or revoked_at is null);
  update public.event_push_instances
     set state='cancelled',cancelled_at=coalesce(cancelled_at,clock_timestamp()),last_error=v_reason,updated_at=clock_timestamp()
   where credential_id=new.credential_id and state in ('pending','leased');
  update public.operational_notification_jobs
     set status='dead',completed_at=coalesce(completed_at,clock_timestamp()),last_error=v_reason,updated_at=clock_timestamp()
   where job_type in ('employee_event_push','employee_native_push')
     and status in ('pending','leased')
     and payload_json->>'credential_id'=new.credential_id::text
     and (status='pending' or leased_until<clock_timestamp());
  return new;
end
$function$

