    LEFT JOIN pg_catalog.pg_class guard_relation ON guard_relation.oid=t.tgrelid
    LEFT JOIN pg_catalog.pg_namespace guard_relation_namespace ON guard_relation_namespace.oid=guard_relation.relnamespace
